UPDATE sections SET content = '{"heading":"Transforming Ideas into <br class=\"hidden md:block\" />\n<span class=\"text-signal-coral\">Digital Reality.</span>","text":"I am a technologist specializing in Generative AI, full-stack web & app development, and digital marketing. With deep expertise in Python, Kotlin, PHP, and modern web frameworks, I architect solutions that solve real business problems.\n\nMy approach blends rigorous engineering with intuitive design, ensuring every product is not only robust but also a joy to use.","imageUrl":"https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEjGadOJC7BcKJWlzYV8dN9hRl1Q2hPjjJJjYYb92PUINpqGY-wCEQUqYAL8t11co2KvpepBr_XXoAnYvPtn8iWpcpsoAyDiso6AM9fGzlyx7QFN5t3ftdGte1fcLEu91dMWwEdUVDU96Z-st4Kh_p8vYEalBl3BVZ-QCkriQEiMRUtqrpDybAOkF2tyWn8/s1600/Professional%20Photo.png","badgeLabel":"Based in","badgeValue":"Bihar, India","bentoLabel":"Founder","bentoTitle":"Techily Fly","bentoDescription":"My technology company, delivering scalable digital platforms and AI automation solutions.","bentoImage":"/logo-dark.png","bentoLink":"https://techilyfly.com"}' WHERE section_id = 'about';
